queries.query:
// Script para monitoreo de generadores en el Observatorio Rubin
// Consulta datos del generador ESS.agcGenset150 incluyendo estado, entradas y temperatura

from(bucket: "efd/autogen")
  // Definir rango de tiempo desde variables de panel
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)

  // Filtrar la medición específica y campos requeridos
  |> filter(fn: (r) =>
      r._measurement == "lsst.sal.ESS.agcGenset150" and
      (r._field == "running" or 
       r._field == "multiInput22" or 
       r._field == "engineOilTemperature" or
       r._field == "engineHours")  // Añadido campo para horas del motor
  )

  // Transformar de formato largo a ancho para facilitar cálculos
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")

  // Calcular campos derivados y formatear la salida
  |> map(fn: (r) => ({
      _time: r._time,
      status: if string(v: r.running) == "1" or string(v: r.running) == "true" then "Running" else "Stopped",
      mean_multiInput22: r.multiInput22,
      mean_engineOilTemperature: r.engineOilTemperature,
      mean_engineHours: r.engineHours,  // Variable incorporada
      _measurement: r._measurement
    }))

